function enterprise(){return `${bread('Entreprise')}${hero({tag:'CONTINUUM OUVERT · ENTREPRISES',heading:'Donnez à vos collaborateurs les bons regards, au bon moment.',desc:'Un abonnement pour permettre à 5 ou 10 collaborateurs de bénéficier de rencontres avec des experts, d’échanges entre professionnels et de ressources utiles à leurs pratiques.',photo:'collectif.webp',compact:true,cta:[btn('Découvrir E5 et E10','#tarifs-entreprises','primary'),btn('Voir les ateliers INTRA','/continuum-intra.html','outline')],more:'<div class="chips"><span class="chip">Accès nominatifs</span><span class="chip">Ouverture à des professionnels extérieurs</span><span class="chip">Ask mutualisées</span></div>'})}<section class="section-compact section-white"><div class="container"><div class="stripes"><div><strong>5 ou 10 accès</strong><p>Une formule simple selon la taille du groupe.</p></div><div><strong>Regards extérieurs</strong><p>Des professionnels d’autres horizons pour nourrir les pratiques.</p></div><div><strong>4 leviers</strong><p>Sessions Horizon, Cercles NORIA, Ask NORIA et ressources.</p></div></div></div></section><section class="section section-cream" id="tarifs-entreprises"><div class="container">${title('ABONNEMENTS ENTREPRISES','Deux formats. Une même intention.','Offrez à vos collaborateurs un accès régulier à l’intelligence collective. Les ateliers INTRA privés ne sont pas inclus dans ces abonnements.')}<div class="billing" data-scope="entreprises" role="group" aria-label="Période de facturation"><button type="button" data-bill="mensuel" aria-pressed="true">Mensuel</button><button type="button" data-bill="annuel" aria-pressed="false">Annuel</button></div><div class="price-grid three" style="margin-top:21px"><div class="price-card featured">${eye('CONTINUUM ENTREPRISE 5')}<h3>Pour une équipe pilote.</h3><div class="cost"><strong data-price-key="e5">249 €</strong><small data-period="e5">/ mois</small></div><p class="period-note" data-note="e5">5 accès nominatifs</p>${li(['5 accès nominatifs','3 Ask NORIA mutualisées par mois','Sessions Horizon et Cercles NORIA','Ressources & Outils'])}<a class="btn btn-primary" href="formule.html?offre=e5-mensuel" data-price-url="e5">Choisir Entreprise 5 ↗</a></div><div class="price-card">${eye('CONTINUUM ENTREPRISE 10')}<h3>Pour avancer plus largement.</h3><div class="cost"><strong data-price-key="e10">449 €</strong><small data-period="e10">/ mois</small></div><p class="period-note" data-note="e10">10 accès nominatifs</p>${li(['10 accès nominatifs','5 Ask NORIA mutualisées par mois','Sessions Horizon et Cercles NORIA','Ressources & Outils'])}<a class="btn btn-teal" href="formule.html?offre=e10-mensuel" data-price-url="e10">Choisir Entreprise 10 ↗</a></div><div class="price-card pilot"><span class="price-badge">Pour essayer</span>${eye('PILOTE ENTREPRISE')}<h3>Tester pendant 3 mois.</h3><div class="cost"><strong>690 €</strong><small>/ 3 mois</small></div><p class="period-note">5 accès nominatifs · sans engagement annuel</p>${li(['5 accès nominatifs pendant 3 mois','Sessions Horizon et Cercles NORIA','Suivi des usages','Bilan en fin de pilote'])}${btn('Lancer un pilote','formule.html?offre=pilote','primary')}<p class="tiny" style="margin:12px 0 0;color:var(--mute)">Si vous poursuivez en annuel, ces 3 mois constituent le début de votre première année.</p></div></div><p class="quiet-note">Au-delà de 10 accès : sur devis. Les Ask non utilisés ne se cumulent pas. Les ateliers INTRA nécessitent un devis distinct.</p></div></section><section class="section section-white"><div class="container">${title('CHOISIR LE BON CADRE','Ouvert, INTRA ou Hybride ?', 'Un abonnement Ouvert n’est pas un atelier privé. Les deux peuvent être complémentaires, sans être obligatoirement associés.') }<div class="choice-grid">${choiceCard({tag:'REGARDS EXTÉRIEURS',t:'CONTINUUM Ouvert',desc:'Vos collaborateurs échangent avec des professionnels et bénéficient des quatre leviers de l’abonnement.',price:'Dès 249 €/mois',image:'continuum-officiel.webp',href:'#tarifs-entreprises',cta:'Comparer E5 et E10'})}${choiceCard({tag:'ATELIERS INTERNES',t:'CONTINUUM INTRA',desc:'Votre équipe travaille collectivement ses propres situations dans un espace privé, facilité par NORIA.',price:'Sur devis',image:'intra-photo.webp',href:'/continuum-intra.html',cta:'Découvrir INTRA'})}${choiceCard({tag:'LES DEUX ENSEMBLE',t:'CONTINUUM Hybride',desc:'Un abonnement pour les regards extérieurs et un atelier privé facturé séparément.',price:'Sur mesure',image:'collectif.webp',href:'hybride.html',cta:'Comprendre l’Hybride'})}</div></div></section>${banner('Construisons la formule adaptée à votre organisation.','Une équipe de cinq, dix collaborateurs ou un périmètre plus large : nous pouvons clarifier les usages et la bonne configuration.',[btn('Échanger sur les besoins de mon équipe','contact.html?besoin=entreprise','primary'),btn('Voir le comparateur','comparatif.html','outline')])}`}
function intra(){return `${bread('CONTINUUM INTRA')}${hero({tag:'CONTINUUM · ENTREPRISES · ATELIERS PRIVÉS',heading:'CONTINUUM <span class="headline-accent">INTRA</span>',desc:'Des ateliers privés, animés par NORIA, pour travailler avec vos collaborateurs sur leurs situations de terrain, croiser les regards et faire émerger des pistes d’action concrètes.',photo:'intra-photo.webp',dark:true,compact:true,cta:[btn('Construire un atelier pour mon équipe','contact.html?besoin=intra','primary'),btn('Découvrir l’Hybride','hybride.html','ghost-light')],more:'<p class="feature-callout">L’intelligence collective au cœur de vos équipes.</p><div class="chips"><span class="chip chip-dark">Ateliers privés</span><span class="chip chip-dark">Sur mesure</span><span class="chip chip-dark">Sans abonnement obligatoire</span></div>'})}<section class="section-compact section-mist"><div class="container"><div class="stripes"><div><strong>Partager</strong><p>Les situations concrètes et les expériences du terrain.</p></div><div><strong>Croiser</strong><p>Les perceptions, pratiques et savoir-faire des collaborateurs.</p></div><div><strong>Avancer</strong><p>Vers des pistes d’action adaptées au contexte de l’équipe.</p></div></div></div></section><section class="section section-white"><div class="container">${title('DES SITUATIONS, PAS DES RECETTES','Au départ, vos enjeux de terrain.','Quelques exemples de situations pouvant faire l’objet d’un atelier dédié.') }<div class="case-grid"><article class="case"><span class="num">01</span><h3>Mieux déléguer</h3><p>Des managers comparent leurs pratiques et identifient des ajustements adaptés à leurs équipes.</p></article><article class="case"><span class="num">02</span><h3>Coopérer entre services</h3><p>Deux équipes confrontent leurs perceptions et cherchent des manières de mieux travailler ensemble.</p></article><article class="case"><span class="num">03</span><h3>Ancrer des apprentissages</h3><p>Une équipe examine ce qu’elle applique réellement après une formation et les obstacles rencontrés.</p></article></div></div></section><section class="section section-cream"><div class="container intra-intro"><div>${title('UNE APPROCHE MODULABLE','Un atelier conçu autour de votre équipe.','Le format, les participants, l’animation, la confidentialité et les modalités de restitution sont cadrés avec votre organisation.')}<div class="chips"><span class="chip">Présentiel ou visio selon cadrage</span><span class="chip">Facilitation</span><span class="chip">Sur devis</span></div><div style="margin-top:24px">${btn('Parler de notre situation','contact.html?besoin=intra','primary')}</div></div><div class="intra-photo"><img src="${asset('intra-photo.webp')}" alt="Visuel CONTINUUM INTRA : atelier avec professionnels autour d’une table" loading="lazy"></div></div></section><section class="section section-white"><div class="container">${title('UNE MÉTHODE SIMPLE','Trois étapes pour passer du sujet à l’action.')}<div class="steps"><div class="step"><span class="step-num">01</span><h3>Cadrer</h3><p>Comprendre votre contexte, vos attentes, le périmètre et les règles de confidentialité.</p></div><div class="step"><span class="step-num">02</span><h3>Faciliter</h3><p>Structurer les échanges entre collaborateurs autour de situations réelles.</p></div><div class="step"><span class="step-num">03</span><h3>Faire émerger</h3><p>Mettre en évidence des priorités et des pistes d’action dans le cadre convenu.</p></div></div></div></section><section class="section section-mist"><div class="container">${title('OUVERT, INTRA, HYBRIDE','Trois configurations, sans confusion.')}<div class="choice-grid">${choiceCard({tag:'AVEC DES REGARDS EXTÉRIEURS',t:'Ouvert',desc:'Accès individuels ou entreprises aux quatre leviers de l’abonnement.',price:'Abonnement',image:'continuum-officiel.webp',href:'entreprises.html',cta:'Découvrir Ouvert'})}${choiceCard({tag:'EN INTERNE',t:'INTRA',desc:'Ateliers privés avec les collaborateurs d’une même organisation.',price:'Sur devis',image:'intra-photo.webp',href:'contact.html?besoin=intra',cta:'Étudier un atelier'})}${choiceCard({tag:'COMBINAISON',t:'Hybride',desc:'Ouvert et INTRA sur des périmètres distincts et facturés séparément.',price:'Sur mesure',image:'collectif.webp',href:'hybride.html',cta:'Découvrir l’Hybride'})}</div></div></section>${banner('Une situation spécifique dans votre équipe ?','Construisons un atelier proportionné à votre besoin. Aucun abonnement Ouvert n’est obligatoire pour bénéficier d’INTRA.',[btn('Demander un devis INTRA','contact.html?besoin=intra','primary'),btn('Comparer les parcours','comparatif.html','outline')])}`}
function hybrid(){return `${bread('Hybride')}${hero({tag:'CONTINUUM · ENTREPRISES · SOLUTION COMBINÉE',heading:'Deux regards sur une même dynamique.',desc:'CONTINUUM Hybride associe les échanges ouverts avec d’autres professionnels et des ateliers privés consacrés aux enjeux internes de votre organisation.',photo:'collectif.webp',compact:true,cta:[btn('Étudier une formule Hybride','contact.html?besoin=hybride','primary'),btn('Comparer les formats','comparatif.html','outline')],more:'<div class="chips"><span class="chip">Abonnement Ouvert</span><span class="chip">Atelier INTRA distinct</span><span class="chip">Sur mesure</span></div>'})}<section class="section section-white"><div class="container">${title('LA LOGIQUE HYBRIDE','Les regards extérieurs. Les situations intérieures.','Deux modalités complémentaires, que l’entreprise peut articuler en fonction de ses besoins.',true)}<div class="hybrid-connect"><div class="hybrid-panel">${eye('01 · CONTINUUM OUVERT')}<h3>Prendre du recul avec d’autres professionnels.</h3><p>Vos collaborateurs disposent des leviers de l’abonnement : Sessions Horizon, Cercles NORIA, Ask NORIA et ressources, selon la formule E5 ou E10.</p>${link('Voir les abonnements entreprises','entreprises.html')}</div><div class="hybrid-middle"><span class="round-icon" aria-hidden="true">+</span></div><div class="hybrid-panel">${eye('02 · CONTINUUM INTRA')}<h3>Travailler vos enjeux en équipe.</h3><p>Un atelier privé facilite les échanges autour de situations internes réelles, avec un cadre et une intervention définis sur devis.</p>${link('Voir les ateliers INTRA','/continuum-intra.html')}</div></div><div class="hybrid-terms"><strong>Une règle simple, à conserver.</strong><p>L’abonnement Ouvert et les ateliers INTRA sont deux prestations distinctes, avec un périmètre et une facturation propres. Aucune inclusion automatique d’INTRA dans les abonnements E5/E10.</p></div></div></section><section class="section section-cream"><div class="container">${title('UN PARCOURS SANS SURCHARGE','Comment construire l’Hybride ?')}<div class="steps"><div class="step"><span class="step-num">01</span><h3>Choisir l’accès Ouvert</h3><p>Définir le nombre d’accès nominatifs et les usages attendus.</p></div><div class="step"><span class="step-num">02</span><h3>Cadrer les ateliers</h3><p>Identifier les situations de terrain, la confidentialité et les objectifs de l’INTRA.</p></div><div class="step"><span class="step-num">03</span><h3>Contractualiser chaque volet</h3><p>Formaliser séparément l’abonnement et les interventions privées selon devis.</p></div></div><div class="offer-banner" style="margin-top:40px"><div><span class="status">Une solution construite sur mesure</span><strong>Pas de forfait Hybride inventé.</strong><p>Les prix de l’abonnement restent ceux d’E5 ou E10 ; la partie INTRA est proposée sur devis.</p></div>${btn('Parler de ma configuration','contact.html?besoin=hybride','primary')}</div></div></section>${banner('Votre équipe a besoin des deux univers ?','Commençons par les usages et les situations à travailler, avant de dimensionner une proposition adaptée.',[btn('Échanger avec NORIA','contact.html?besoin=hybride','primary')])}`}
function comparison(){return `${bread('Trouver mon format')}${hero({tag:'CONTINUUM · AIDE À L’ORIENTATION',heading:'Quel CONTINUUM pour votre situation ?',desc:'Vous pouvez avancer individuellement, ouvrir un accès à plusieurs collaborateurs ou organiser des ateliers privés. Quelques repères suffisent pour identifier la bonne direction.',photo:'continuum-officiel.webp',compact:true,cta:[btn('Comparer les offres','#comparaison','primary')],more:'<div class="chips"><span class="chip">Sans parcours imposé</span><span class="chip">Tarifs distincts</span><span class="chip">Aucun achat forcé</span></div>'})}<section class="section section-white" id="comparaison"><div class="container">${title('QUEL EST VOTRE BESOIN ?','Une question, une orientation concrète.','Sélectionnez la situation qui vous ressemble le plus ; vous pourrez ensuite consulter la page correspondante.')}<div class="selection"><div class="selection-panel"><div class="selection-options" role="radiogroup" aria-label="Mon besoin">${[['moi','Je souhaite progresser et bénéficier d’un appui régulier pour moi.'],['equipe','Je souhaite ouvrir CONTINUUM à plusieurs collaborateurs.'],['prive','Nous devons travailler en interne sur nos situations d’équipe.'],['mixte','Nous voulons combiner regards extérieurs et ateliers privés.'],['incertain','Notre besoin n’est pas encore complètement défini.']].map(([v,t],i)=>`<label><input type="radio" name="besoin" value="${v}" ${i===0?'checked':''}><span>${t}</span></label>`).join('')}</div></div><aside class="result-panel" id="rec-result" aria-live="polite"></aside></div></div></section><section class="section section-mist"><div class="container">${title('TOUTES LES FORMULES','Les différences, sans ambiguïté.')}${compareTable()}<p class="quiet-note">L’Hybride combine une formule Ouvert et un atelier INTRA sous devis distinct. Les tarifs promotionnels Pionniers et Pilote dépendent des conditions et de la disponibilité réellement confirmées.</p></div></section>${banner('Vous hésitez encore ?','Un premier échange permet de choisir une solution proportionnée à votre besoin, sans imposer d’abonnement.',[btn('Échanger avec NORIA','contact.html','primary')])}`}
