function formula(){const k=new URLSearchParams(location.search).get('offre')||'individuel-mensuel';const o=offerings[k]||offerings['individuel-mensuel'];document.title=`${o.title} | NORIA HORIZON`;return `${bread(o.title)}${hero({tag:'CONTINUUM · SÉLECTION DE FORMULE',heading:o.title,desc:o.text,photo: k.startsWith('e')||k==='pilote'?'collectif.webp':'continuum-officiel.webp',compact:true,cta:[btn('Voir les autres offres',o.back,'outline')],more:`<p class="feature-callout">${o.sub}</p>`})}<section class="section section-white"><div class="container selection"><div><div class="section-header">${eye('VOTRE SÉLECTION')}<h2>Un choix clair, avant de poursuivre.</h2><p>Retrouvez ici la formule sélectionnée, les prestations comprises et les conditions, avant de vous engager.</p></div><div class="formule-detail"><div class="cost">${o.price}</div><p class="value">${o.sub}</p>${li(o.items)}<p class="quiet-note">${o.warning}</p></div></div><aside class="result-panel">${eye('PAIEMENT SÉCURISÉ')}<h3>Je choisis cette formule.</h3><p>Le paiement sécurisé s’ouvre dans un nouvel onglet. Votre code d’accès à l’espace membre CONTINUUM vous est ensuite transmis.</p>${STRIPE[k]?btn('Je m’abonne · '+o.price,STRIPE[k],'primary','target="_blank" rel="noopener"'):btn('Demander à activer cette offre','contact.html','primary')}<p class="tiny" style="margin:14px 0 0;color:#b8cfd1">Une question avant de vous engager ? <a href="contact.html?besoin=${k.startsWith('e')||k==='pilote'?'entreprise':'individuel'}" style="text-decoration:underline">Échanger avec NORIA</a></p></aside></div></section>${banner('Besoin d’un autre regard avant de choisir ?', 'Vous pouvez comparer les formules ou demander à NORIA de vous orienter.',[btn('Comparer les formats','comparatif.html','primary'),btn('Échanger avec NORIA','contact.html','outline')])}`}
function contact(){return `${bread('Échanger avec NORIA')}${hero({tag:'CONTINUUM · PREMIER CONTACT',heading:'Parlons de votre situation.',desc:'Une question sur une formule, un projet pour votre équipe ou une envie de progresser dans la durée ? Nous vous aidons à identifier le bon cadre.',photo:'atelier.webp',compact:true,cta:[btn('Retour à CONTINUUM','continuum.html','outline')]})}<section class="section section-white"><div class="container selection"><div class="selection-panel">${eye('PRÉPARER MA DEMANDE')}<h2 style="font-size:43px;margin:15px 0">Sur quel sujet souhaitez-vous échanger ?</h2><p class="subtle">Indiquez le sujet et quelques mots sur votre situation : vous complétez ensuite vos coordonnées, et l’équipe NORIA vous répond.</p><form id="contact-form"><label for="contact-topic" class="kicker" style="display:block;margin-bottom:8px">Objet de la demande</label><select id="contact-topic" name="topic" style="width:100%;padding:13px;border-radius:9px;border:1px solid #d6cfc2;background:white;font:inherit;color:var(--ink)"><option value="individuel">CONTINUUM individuel</option><option value="entreprise">CONTINUUM Entreprise</option><option value="intra">CONTINUUM INTRA</option><option value="hybride">CONTINUUM Hybride</option><option value="autre">Conseil sur le bon parcours</option></select><label for="contact-msg" class="kicker" style="display:block;margin:22px 0 8px">Votre situation, en quelques mots</label><textarea id="contact-msg" name="msg" rows="6" placeholder="Décrivez votre besoin sans données sensibles…" style="width:100%;padding:14px;border-radius:9px;border:1px solid #d6cfc2;background:white;font:inherit;color:var(--ink);resize:vertical"></textarea><button class="btn btn-primary" type="submit" style="margin-top:16px">Continuer ma demande ↗</button></form></div><aside class="result-panel">${eye('UN PREMIER ÉCHANGE')}<h3>Pas de formule imposée.</h3><p>CONTINUUM peut s’utiliser avant, après ou indépendamment d’une formation ; INTRA reste accessible sans abonnement. Nous orientons selon votre besoin.</p><div class="divider" style="background:#486a74;margin:25px 0"></div><p class="small">NORIA HORIZON<br><a style="color:#f2cfb5;text-decoration:underline" href="mailto:noriahorizoncontacts@gmail.com">noriahorizoncontacts@gmail.com</a></p></aside></div></section>`}
function rootBody(page){const pages={index:home,continuum,individuel:individual,entreprises:enterprise,intra,hybride:hybrid,comparatif:comparison,formule:formula,contact};return (pages[page]||continuum)()}
function init(){const page=document.body.dataset.page||'continuum';const root=document.getElementById('app');root.innerHTML=siteHeader(page)+`<main id="contenu">${rootBody(page)}</main>`+siteFooter()+'';
const m=$('.mobile-trigger'),nav=$('.mobile-nav');m?.addEventListener('click',()=>{const on=m.getAttribute('aria-expanded')==='true';m.setAttribute('aria-expanded',String(!on));nav.classList.toggle('open',!on)});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');m?.setAttribute('aria-expanded','false')}));
document.querySelectorAll('.acc button').forEach(b=>b.addEventListener('click',()=>{const row=b.closest('.acc');const is=row.classList.toggle('open');b.setAttribute('aria-expanded',String(is))}));
document.querySelectorAll('.billing').forEach(gr=>gr.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{const annual=b.dataset.bill==='annuel';gr.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));for(const key of ['e5','e10']){const price=$(`[data-price-key="${key}"]`),period=$(`[data-period="${key}"]`),note=$(`[data-note="${key}"]`),cta=$(`[data-price-url="${key}"]`);if(!price)continue;price.textContent=key==='e5'?(annual?'2 490 €':'249 €'):(annual?'4 490 €':'449 €');period.textContent=annual?'/ an':'/ mois';note.textContent=annual?(key==='e5'?'5 accès nominatifs · 498 € économisés':'10 accès nominatifs · 898 € économisés'):(key==='e5'?'5 accès nominatifs':'10 accès nominatifs');cta.href=`formule.html?offre=${key}-${annual?'annuel':'mensuel'}`;}})));
const recs={moi:['CONTINUUM pour moi','Un abonnement individuel pour progresser et bénéficier régulièrement d’autres regards.','59 €/mois ou 590 €/an','individuel.html'],equipe:['CONTINUUM Entreprise','Une formule Ouvert de 5 ou 10 accès nominatifs, avec Ask mutualisées selon l’abonnement.','249 €/mois (E5) ou 449 €/mois (E10)','entreprises.html'],prive:['CONTINUUM INTRA','Des ateliers privés facilités pour travailler sur les situations propres à votre équipe.','Sur devis · sans abonnement obligatoire','/continuum-intra.html'],mixte:['CONTINUUM Hybride','Un abonnement Ouvert pour les regards extérieurs, complété par des ateliers INTRA privés facturés séparément.','Sur mesure · deux cadres distincts','hybride.html'],incertain:['Échanger avec NORIA','Commençons par clarifier votre besoin avant de vous proposer une formule ou un accompagnement.','Premier échange sans engagement','contact.html']};
function recUpdate(){const v=$('input[name="besoin"]:checked')?.value||'moi';const r=recs[v];const el=$('#rec-result');if(el)el.innerHTML=`${eye('ORIENTATION SUGGÉRÉE')}<h3>${r[0]}</h3><p>${r[1]}</p><p class="feature-callout" style="font-size:25px;color:#f2c19f">${r[2]}</p>${btn('Découvrir cette solution',r[3],'primary')}`};document.querySelectorAll('input[name="besoin"]').forEach(x=>x.addEventListener('change',recUpdate));recUpdate();
const topic=new URLSearchParams(location.search).get('besoin');const select=$('#contact-topic');if(select&&topic&&Array.from(select.options).some(x=>x.value===topic))select.value=topic;
$('#contact-form')?.addEventListener('submit',ev=>{ev.preventDefault();const topic=$('#contact-topic')?.selectedOptions?.[0]?.text||'CONTINUUM';const msg=$('#contact-msg')?.value||'Je souhaite échanger sur mon besoin.';try{if(window.parent!==window&&typeof window.parent.openDevisContinuum==='function'){window.parent.openDevisContinuum(topic,msg);return;}}catch(e){}location.href=`mailto:noriahorizoncontacts@gmail.com?subject=${encodeURIComponent('NORIA — Demande concernant '+topic)}&body=${encodeURIComponent('Bonjour,\n\n'+msg+'\n\nBien cordialement,')}`});
}
document.addEventListener('DOMContentLoaded',init);

/* Dans la fenêtre du site principal : les liens vers l'accueil ferment la fenêtre (25 nov. 2026) */
(function(){var p=null;try{if(window.parent!==window&&typeof window.parent.closeAgir==='function')p=window.parent;}catch(e){}
if(!p)return;document.documentElement.classList.add('in-overlay');
document.addEventListener('click',function(e){var a=e.target.closest&&e.target.closest('a[href]');if(!a)return;var h=a.getAttribute('href');
 if(h==='/'||h.indexOf('/#')===0){e.preventDefault();p.closeAgir();var id=h.slice(2);setTimeout(function(){if(id==='noria-prisme'&&p.openPorte){p.openPorte('prisme');return;}if(id==='visages'&&p.openPorte){p.openPorte('experts');return;}var el=id&&p.document.getElementById(id);if(el)el.scrollIntoView({behavior:'smooth'});else p.scrollTo({top:0,behavior:'smooth'});},380);}
});document.addEventListener('keydown',function(e){if(e.key==='Escape')p.closeAgir();});})();
